// === NODE 1: PROCESSAR TRANSCRIÇÃO ===

const body = $json.body;

// Verificar se é transcrição
if (body.event !== 'message.transcription') {
  throw new Error('Evento inválido: esperado message.transcription');
}

// Extrair dados
const transcription = body.transcription || {};
const chatId = body.chatId;
const messageId = body.messageId;
const sessionId = body.sessionId;
const status = body.status;

// Log pra debug
console.log('[TRANSCRIPTION] Recebida:', {
  chatId,
  messageId,
  status,
  text: transcription.text,
  language: transcription.language,
  provider: transcription.provider
});

// Se falhou ou foi skipped
if (status !== 'completed') {
  return {
    json: {
      error: `Transcrição ${status}`,
      chatId,
      messageId
    }
  };
}

// Se não tem texto
if (!transcription.text || transcription.text.trim() === '') {
  return {
    json: {
      error: 'Transcrição vazia',
      chatId,
      messageId
    }
  };
}

// Retornar dados estruturados
return {
  json: {
    type: 'audio_transcription',
    chatId: chatId,
    messageId: messageId,
    sessionId: sessionId,
    text: transcription.text,
    language: transcription.language || 'pt',
    provider: transcription.provider || 'groq',
    model: transcription.model || 'whisper-large-v3-turbo',
    timestamp: new Date().toISOString()
  }
};

// === NODE 2: MONTAR PROMPT PARA ÁUDIO ===

const data = $input.first().json;

// Contexto: sempre marcar que veio de áudio
const systemPrompt = `Você é assistente virtual do escritório Dr. Dênis Bernardo.

⚠️ IMPORTANTE: Esta mensagem veio de um ÁUDIO (não foi digitada).
- Cliente usou voz, então resposta deve ser natural e conversacional
- Confirme que entendeu: "Ouvi seu áudio! Você disse: [resumo]. Tá certo?"

REGRAS:
1. Tom: Informal, empático, como vizinho de confiança
2. Linguagem: Português simples, máx 2-3 frases
3. Sempre confirme o que entendeu do áudio
4. Erros de transcrição: entenda contexto

💬 EXEMPLO:
Cliente (áudio): "Olá, quanto custa o Lawapp?"
Você: "Ouvi seu áudio! A consulta é gratuita. Quer agendar? 😊"

NUNCA invente informações.
Sempre termine: "Precisa de mais alguma coisa?"`;

// User prompt com a transcrição
const userPrompt = `🎤 ÁUDIO TRANSCRITO:
"${data.text}"

LÍNGUA DETECTADA: ${data.language}
PROVIDER: ${data.provider} (${data.model})

Responda confirmando que ouviu o áudio e ajude o cliente.`;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    chatId: data.chatId,
    messageId: data.messageId,
    text: data.text,
    isAudio: true
  }
};

// === NODE 4: LIMPAR RESPOSTA ===

let text = $input.first().json.text;

// Remover tags <think>
text = text.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

// Pegar dados
const prevData = $item("0").$node["2. Montar Prompt (Áudio)"].json;

return {
  json: {
    chatId: prevData.chatId,
    text: text,
    messageId: prevData.messageId,
    wasAudio: true
  }
};
